'use strict';

function renderUserTiltfile(services) {
  const lines = [
    '# Generated by Launchpad from services registered in the Dashboard.',
    '# Source of truth is dev-dashboard/data/launchpad.db. Change services in the UI.',
    '',
  ];
  (services || []).forEach((service) => {
    const labels = [service.section];
    if (service.framework) labels.push(`fw-${service.framework}`);
    lines.push('local_resource(');
    lines.push(`    ${JSON.stringify(service.name)},`);
    lines.push(`    serve_cmd=${JSON.stringify(service.command)},`);
    lines.push(`    serve_dir=${JSON.stringify(service.path)},`);
    if (service.needsAws) {
      lines.push("    resource_deps=['aws-creds'],");
    }
    if (service.port) {
      lines.push('    readiness_probe=probe(');
      lines.push(`        tcp_socket=tcp_socket_action(port=${service.port}),`);
      lines.push('        period_secs=15,');
      lines.push('    ),');
      lines.push('    links=[');
      lines.push(`        link(${JSON.stringify(`http://localhost:${service.port}`)}, 'Open'),`);
      lines.push('    ],');
    }
    lines.push(`    labels=[${labels.map((label) => JSON.stringify(label)).join(', ')}],`);
    lines.push(')');
    lines.push('');
  });
  return `${lines.join('\n')}`;
}

module.exports = { renderUserTiltfile };
